css-background-position.css:
:root { --page:#eef6f3; --ink:#183a34; --muted:#54716b; --accent:#007c64; --line:#9bc8bd; --soft:#dff2ec; --orange:#df7419; }
html,body { margin:0; background:var(--page); color:var(--ink); font-family:Roboto,sans-serif; }
.shell { box-sizing:border-box; width:100%; max-width:940px; margin:0 auto; padding:0 28px 60px; }
.topbar,.topbar nav,.samples,footer { display:flex; }
.topbar { justify-content:space-between; align-items:center; padding:24px 0; border-bottom:1px solid var(--line); color:var(--muted); font-size:13px; }
.topbar nav { gap:8px; }
.topbar nav a { padding:4px 8px; border:1px solid var(--accent); text-decoration:none; }
.brand { color:var(--ink); font-weight:bold; letter-spacing:2px; text-decoration:none; }
main { padding-top:42px; }
.eyebrow { margin:0 0 10px; color:var(--accent); font-size:12px; font-weight:bold; letter-spacing:1px; }
h1 { margin:0; font-size:44px; line-height:1.05; }
.intro { max-width:720px; margin:20px 0 34px; color:var(--muted); font-size:18px; line-height:1.5; }
.card { padding:24px; background:#fff; border:1px solid var(--line); }
.samples { gap:18px; }
.sample { box-sizing:border-box; flex:1; min-width:0; height:180px; padding:18px; background-color:var(--soft); background-image:radial-gradient(circle, var(--orange) 0, var(--orange) 46%, transparent 50%); background-size:54px 54px; background-repeat:no-repeat; border:1px dashed var(--accent); }
.sample span { display:inline-block; padding:5px 8px; background:rgba(255,255,255,.86); }
.right-center { background-position-x:right 18px; background-position-y:center; }
.center-bottom { background-position-x:center; background-position-y:bottom 12px; }
.left-top { background-position-x:left 14px; background-position-y:top 10px; }
footer { justify-content:space-between; margin-top:38px; padding-top:20px; border-top:1px solid var(--line); font-size:12px; }
a { color:var(--accent); }
@media (max-width:700px) { .samples { display:block; } .sample { width:100%; margin-bottom:18px; } h1 { font-size:34px; } }

css-individual-transforms.css:
:root { --page:#f5f1fb; --ink:#302145; --muted:#6b6078; --accent:#6d3bb2; --line:#cdbce4; --soft:#eee5f8; --orange:#df7419; }
html,body { margin:0; background:var(--page); color:var(--ink); font-family:Roboto,sans-serif; }
.shell { box-sizing:border-box; width:100%; max-width:940px; margin:0 auto; padding:0 28px 60px; }
.topbar,.topbar nav,.stage,footer { display:flex; }
.topbar { justify-content:space-between; align-items:center; padding:24px 0; border-bottom:1px solid var(--line); color:var(--muted); font-size:13px; }
.topbar nav { gap:8px; }
.topbar nav a { padding:4px 8px; border:1px solid var(--accent); text-decoration:none; }
.brand { color:var(--ink); font-weight:bold; letter-spacing:2px; text-decoration:none; }
main { padding-top:42px; }
.eyebrow,.label { margin:0 0 10px; color:var(--accent); font-size:12px; font-weight:bold; letter-spacing:1px; }
h1 { margin:0; font-size:44px; line-height:1.05; }
.intro { max-width:720px; margin:20px 0 34px; color:var(--muted); font-size:18px; line-height:1.5; }
.card { margin-bottom:20px; padding:24px; overflow:hidden; background:#fff; border:1px solid var(--line); }
.stage { min-height:180px; gap:24px; align-items:center; justify-content:space-around; background:var(--soft); border:1px dashed var(--line); }
.sample { box-sizing:border-box; width:150px; height:72px; padding:24px 12px; background:var(--accent); color:#fff; text-align:center; transform-origin:center; }
.translated { translate:18px -10px; }
.rotated { rotate:-8deg; }
.scaled { scale:1.18; }
.combined-stage { height:160px; padding:20px; overflow:hidden; background:var(--soft); border:1px dashed var(--line); }
.combined { box-sizing:border-box; width:310px; padding:24px 16px; background:var(--orange); color:#fff; text-align:center; transform-origin:left top; translate:34px 18px; rotate:5deg; scale:1.08; transform:translateX(12px); }
footer { justify-content:space-between; margin-top:38px; padding-top:20px; border-top:1px solid var(--line); font-size:12px; }
a { color:var(--accent); }
@media (max-width:700px) { .stage { display:block; padding:24px; } .sample { width:100%; margin-bottom:24px; } h1 { font-size:34px; } }

css-visual-properties.css:
*{box-sizing:border-box}
html{background:#eef7f4;color:#173c36;font-family:Arial,sans-serif}
body{margin:0;padding:22px}
.shell{max-width:1040px;margin:0 auto;background:#fff;border:1px solid #9ac9bd}
.topbar{display:flex;align-items:center;gap:18px;padding:14px 20px;background:#173c36;color:#fff}
.topbar nav{display:flex;gap:8px}.topbar a{color:#fff}.topbar .brand{font-weight:bold;text-decoration:none}.topbar span{margin-left:auto}
main{padding:28px}.eyebrow,.label{margin:0 0 9px;color:#6d28d9;font-size:12px;font-weight:bold;letter-spacing:1px}.label{color:#087f68}
h1{margin:0;font-size:36px;line-height:1.05}.intro{max-width:720px;color:#4d6d67;font-size:18px;line-height:1.5}
.card{margin-top:20px;padding:20px;border:1px solid #b7d9d1;background:#fbfdfc}.grid,.text-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.controls{display:flex;align-items:center;flex-wrap:wrap;gap:22px}.controls label{display:flex;align-items:center;gap:7px}.controls input[type=range]{width:190px}.controls progress{width:190px}
.accent{accent-color:#c026d3}
.scroll-sample{height:112px;overflow:scroll;scrollbar-color:#6d28d9 #eadffc;scrollbar-width:thin;padding:8px;background:#f7f2ff}.scroll-sample p{margin:0 0 24px}
.images{display:flex;gap:18px}.images figure{margin:0}.images img{width:112px;height:112px;border:1px solid #173c36}.images figcaption{text-align:center;margin-top:5px}.images #smooth-image{image-rendering:smooth}.images #pixelated-image{image-rendering:pixelated}
.text-box{margin:0;min-width:0;padding:14px;background:#effaf7;border-left:4px solid #0f9f82;line-height:1.45}.wrap{white-space-collapse:collapse;text-wrap-mode:wrap}.nowrap{overflow:hidden;text-wrap:nowrap stable}.justified{text-align:justify;text-justify:inter-word}.underlined{text-decoration:underline 2px #6d28d9;text-underline-position:under}
.image-list{list-style-image:url("assets/pixel-grid.png");image-rendering:pixelated;font-size:18px;line-height:1.7}
footer{display:flex;justify-content:space-between;padding:18px 28px;border-top:1px solid #b7d9d1}footer a{color:#6d28d9}
@media (max-width:700px){body{padding:8px}main{padding:18px}.grid,.text-grid{grid-template-columns:1fr}.controls{align-items:flex-start;flex-direction:column}h1{font-size:29px}}

html-css-stress.css:
:root { color-scheme: light; --ink:#173630; --muted:#49685f; --paper:#f3f5ef; --panel:#fff; --line:#c9d9d0; --accent:#087f72; --warm:#fa7b43; --space:20px; font-family:Arial,sans-serif; font-size:16px; }
* { box-sizing:border-box; }
html { scroll-behavior:smooth; scroll-padding-top:20px; }
body { margin:0; background:var(--paper); color:var(--ink); line-height:1.5; }
.workspace { max-width:1480px; margin:0 auto; padding:28px; }
a { color:#076a60; text-underline-offset:3px; }
a:hover { color:#974318; }
:focus-visible { outline:3px solid #b44409; outline-offset:4px; }
.skip-link { position:fixed; top:8px; left:8px; transform:translateY(-150%); background:#fff; padding:12px; z-index:1000; }
.skip-link:focus { transform:translateY(0); }
.hero { padding:32px 36px 30px; background:#153f36; color:#fff; border-radius:4px; }
.hero a { color:#bdedc4; }
.hero-top { display:flex; justify-content:space-between; gap:16px; flex-wrap:wrap; font-size:13px; }
.edition,.eyebrow { font-size:12px; letter-spacing:.12em; text-transform:uppercase; font-weight:bold; }
.eyebrow { color:var(--accent); margin:0 0 8px; }
.hero .eyebrow { color:#b7e5b5; margin-top:38px; }
h1 { font-size:clamp(42px,6vw,80px); line-height:1.02; letter-spacing:-.035em; margin:14px 0 20px; }
h1 span { color:#bfe8aa; }
.lead { font-size:20px; max-width:660px; }
.inventory-stats { display:flex; gap:48px; flex-wrap:wrap; border-top:1px solid #538071; margin-top:28px; padding-top:10px; }
.inventory-stats p { margin:8px 0; }
.inventory-stats strong { display:block; font-size:32px; line-height:1.2; }
.inventory-stats span { font-size:13px; color:#d1e6d9; }
.scope-note { max-width:970px; color:#d1e6d9; font-size:13px; margin-top:20px; }
.section-nav { display:flex; gap:10px 20px; flex-wrap:wrap; padding:20px 0; border-bottom:1px solid var(--line); margin-bottom:24px; }
.section-nav a { font-weight:bold; font-size:14px; }
.panel { background:var(--panel); border:1px solid var(--line); padding:24px; margin-bottom:24px; min-width:0; }
.section-heading { display:flex; gap:16px; justify-content:space-between; align-items:start; margin-bottom:16px; }
h2 { font-size:28px; line-height:1.2; margin:0 0 16px; letter-spacing:-.02em; }
h3 { font-size:18px; margin:0 0 12px; }
h4,h5,h6 { margin:8px 0; }
p { margin:0 0 14px; }
.chip { background:#e5f0d9; color:#26491a; padding:5px 10px; font-size:12px; white-space:nowrap; border-radius:20px; }
.control-row { display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin:18px 0; }
button,input,select,textarea { font:inherit; accent-color:var(--accent); }
button,input[type=button],input[type=submit],input[type=reset] { padding:9px 14px; border:1px solid #087f72; background:#e1f3ec; color:#123e33; cursor:pointer; border-radius:3px; }
button:hover { background:#ccebdc; }
button:disabled { color:#65736e; border-color:#b7c5be; background:#eef1ed; cursor:default; }
#benchmark-start { background:#087f72; color:#fff; }
input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]):not([type=image]):not([type=hidden]),select,textarea { max-width:100%; min-width:0; padding:9px 10px; border:1px solid #78958a; background:#fff; color:var(--ink); border-radius:3px; }
input:read-only { background:#f1f4ef; }
input:disabled,select:disabled { opacity:.65; }
input:user-invalid { border-color:#b53928; background:#fff0ea; }
input::placeholder,textarea::placeholder { color:#64776f; opacity:1; }
.metrics { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:12px; margin:20px 0; }
.metrics>div { border-top:2px solid #a9c4b5; padding:12px 0; }
.metrics span { display:block; color:var(--muted); font-size:12px; }
.metrics output { font-family:monospace; font-size:24px; font-weight:bold; }
#benchmark-status { color:var(--muted); font-size:14px; }
details { border-top:1px solid var(--line); padding:14px 0; }
summary { cursor:pointer; font-weight:bold; margin-bottom:8px; }
.motion-switch { margin:0 8px 24px 4px; width:18px; height:18px; vertical-align:middle; }
.motion-label { font-weight:bold; }
.motion-hint { color:var(--muted); font-size:13px; margin-left:16px; }
#run-motion ~ section .motion { animation-play-state:paused; }
#run-motion:checked ~ section .motion { animation-play-state:running; }
.card-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:18px; }
.specimen { margin:0; border:1px solid #d3dfd7; padding:18px; min-width:0; overflow-wrap:anywhere; }
.specimen p:last-child { margin-bottom:0; }
pre { padding:12px; background:#eff4ee; overflow:auto; font-size:13px; }
code,kbd,samp { font-family:monospace; }
kbd { border:1px solid #a5b8ac; border-bottom-width:3px; padding:1px 5px; border-radius:3px; }
blockquote { margin:16px 0; border-left:3px solid var(--warm); padding-left:14px; color:#4c645a; }
blockquote footer { font-size:13px; }
dt { font-weight:bold; } dd { margin:0 0 10px 20px; }
menu { padding-left:20px; }
.ruby-line { line-height:3; font-size:22px; }
.callout { background:#edf5e7; padding:18px; margin:20px 0; }
fieldset { border:1px solid var(--line); padding:18px; margin:18px 0; min-width:0; }
legend { padding:0 8px; font-weight:bold; }
.form-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:18px; }
.form-grid>label { display:flex; flex-direction:column; gap:6px; font-size:14px; }
.form-grid>div>label,.radio-group label { display:block; margin:8px 0; }
.radio-group { margin:0; padding:10px; }
.gauges { display:flex; flex-wrap:wrap; gap:24px; }
.gauges label { display:flex; gap:10px; flex-direction:column; }
progress,meter { width:180px; height:20px; }
.custom-select,.custom-select::picker(select) { appearance:base-select; }
dialog { color:var(--ink); background:#fff; border:1px solid var(--accent); max-width:480px; padding:28px; }
dialog::backdrop { background:rgb(10 40 32 / .65); backdrop-filter:blur(5px); }
dialog label { display:block; margin-bottom:18px; }
[popover] { max-width:320px; padding:20px; border:2px solid var(--accent); background:#fff; color:var(--ink); }
.table-scroll { overflow:auto; max-height:400px; scrollbar-gutter:stable; }
.data-table { width:100%; min-width:620px; border-collapse:collapse; table-layout:fixed; }
.data-table caption { text-align:left; color:var(--muted); padding-bottom:12px; font-size:13px; }
.data-table th,.data-table td { border:1px solid #c4d6ca; padding:10px 12px; text-align:left; }
.data-table thead { position:sticky; top:0; z-index:2; background:#dbeade; }
.data-table tbody tr:nth-child(even) { background:#f0f5ee; }
.data-table tbody tr:hover { background:#e3efcb; }
.data-table .col-index { width:20%; } .data-table .col-value { background:#eff4df; }
.data-table tfoot { font-weight:bold; background:#dbeade; }
img,video,canvas,iframe,object,embed,svg { max-width:100%; }
audio { width:100%; margin:8px 0; }
video,canvas { display:block; height:auto; margin:12px 0; }
iframe { border:1px solid var(--line); }
.embedded-stack { display:flex; flex-direction:column; align-items:flex-start; gap:19px; }
figcaption { color:var(--muted); font-size:13px; margin-top:10px; }
.inline-svg { display:block; margin-top:16px; }
stress-note { display:block; }
math { font-size:28px; min-height:90px; }
.load-seed { display:block; }
.load-group { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:8px; margin-bottom:8px; }
.load-card { border:1px solid #b8d0be; padding:10px; background:#f3f7e9; min-width:0; }
.load-card strong { font:12px monospace; }
.load-bars { display:flex; align-items:end; gap:3px; height:32px; margin-top:8px; }
.load-bars span { display:block; flex:1; background:#24836c; }
.load-bars span:nth-child(2) { background:#75ad73; }
.load-bars span:nth-child(3) { background:#ed935e; }
#stress-extra { margin-top:8px; }
.element-index { display:flex; flex-wrap:wrap; gap:8px; }
.element-index code { background:#edf4e8; border:1px solid #d0dfc8; padding:4px 8px; color:#294c22; font-size:12px; }
.catalog-search label { display:block; font-weight:bold; margin-bottom:8px; }
.catalog-search input { width:380px; }
.catalog-search output { margin-left:16px; color:var(--muted); }
.catalog-search p { font-size:13px; color:var(--muted); margin-top:12px; }
.page-footer { padding:24px 0 36px; border-top:1px solid var(--line); color:var(--muted); font-size:13px; }
[hidden] { display:none !important; }
::selection { background:#c4eaa5; color:#153f36; }
@media (max-width:1000px) { .card-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .form-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .load-group { grid-template-columns:repeat(4,minmax(0,1fr)); } }
@media (max-width:600px) { .workspace { padding:12px; } .hero { padding:22px; } .panel { padding:16px; } .card-grid,.form-grid { grid-template-columns:1fr; } .metrics { grid-template-columns:repeat(2,minmax(0,1fr)); } .inventory-stats { gap:22px; } .motion-hint { display:block; margin:0 0 20px; } .section-heading { display:block; } .load-group { grid-template-columns:repeat(3,minmax(0,1fr)); } h2 { font-size:24px; } }
@media (prefers-reduced-motion:reduce) { html { scroll-behavior:auto; } *,*::before,*::after { animation-play-state:paused !important; transition-duration:0s !important; } }
@media (forced-colors:active) { .hero,.load-card { border:1px solid CanvasText; } .load-bars span { background:Highlight; } }
@media print { .section-nav,.controls-panel,.motion-switch,.motion-label,.motion-hint,.catalog-search { display:none; } .workspace { max-width:none; padding:0; } .panel { break-inside:avoid; } body { background:white; color:black; } .hero { background:white; color:black; } .hero span,.hero p { color:black; } a { color:inherit; } }



.category-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px;margin-bottom:24px}
.category-card{display:block;padding:22px;background:#fff;border:1px solid var(--line);color:var(--ink);text-decoration:none;min-width:0}
.category-card:hover,.category-card:focus-visible{border-color:var(--accent);background:#eaf6ee}
.category-card h2{font-size:22px;margin:4px 0 10px}.category-card p{color:var(--muted);margin:0}
.category-card .eyebrow{font-size:11px;color:var(--accent)}.category-card .count{font-weight:bold;color:#076a60;font-size:13px;margin-top:12px}

