.specimen { margin:0; border:1px solid #d3dfd7; padding:18px; min-width:0; overflow-wrap:anywhere; }
.specimen p:last-child { margin-bottom:0; }
pre { padding:12px; background:#eff4ee; overflow:auto; font-size:13px; }
code,kbd,samp { font-family:monospace; }
kbd { border:1px solid #a5b8ac; border-bottom-width:3px; padding:1px 5px; border-radius:3px; }
blockquote { margin:16px 0; border-left:3px solid var(--warm); padding-left:14px; color:#4c645a; }
blockquote footer { font-size:13px; }
dt { font-weight:bold; } dd { margin:0 0 10px 20px; }
menu { padding-left:20px; }
.ruby-line { line-height:3; font-size:22px; }
.callout { background:#edf5e7; padding:18px; margin:20px 0; }
fieldset { border:1px solid var(--line); padding:18px; margin:18px 0; min-width:0; }
legend { padding:0 8px; font-weight:bold; }
.form-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:18px; }
.form-grid>label { display:flex; flex-direction:column; gap:6px; font-size:14px; }
.form-grid>div>label,.radio-group label { display:block; margin:8px 0; }
.radio-group { margin:0; padding:10px; }
.gauges { display:flex; flex-wrap:wrap; gap:24px; }
.gauges label { display:flex; gap:10px; flex-direction:column; }
progress,meter { width:180px; height:20px; }
.custom-select,.custom-select::picker(select) { appearance:base-select; }
dialog { color:var(--ink); background:#fff; border:1px solid var(--accent); max-width:480px; padding:28px; }
dialog::backdrop { background:rgb(10 40 32 / .65); backdrop-filter:blur(5px); }
dialog label { display:block; margin-bottom:18px; }
[popover] { max-width:320px; padding:20px; border:2px solid var(--accent); background:#fff; color:var(--ink); }
.table-scroll { overflow:auto; max-height:400px; scrollbar-gutter:stable; }
.data-table { width:100%; min-width:620px; border-collapse:collapse; table-layout:fixed; }
.data-table caption { text-align:left; color:var(--muted); padding-bottom:12px; font-size:13px; }
.data-table th,.data-table td { border:1px solid #c4d6ca; padding:10px 12px; text-align:left; }
.data-table thead { position:sticky; top:0; z-index:2; background:#dbeade; }
.data-table tbody tr:nth-child(even) { background:#f0f5ee; }
.data-table tbody tr:hover { background:#e3efcb; }
.data-table .col-index { width:20%; } .data-table .col-value { background:#eff4df; }
.data-table tfoot { font-weight:bold; background:#dbeade; }
img,video,canvas,iframe,object,embed,svg { max-width:100%; }
audio { width:100%; margin:8px 0; }
video,canvas { display:block; height:auto; margin:12px 0; }
iframe { border:1px solid var(--line); }
.embedded-stack { display:flex; flex-direction:column; align-items:flex-start; gap:19px; }
figcaption { color:var(--muted); font-size:13px; margin-top:10px; }
.inline-svg { display:block; margin-top:16px; }
stress-note { display:block; }
math { font-size:28px; min-height:90px; }
.load-seed { display:block; }
.load-group { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:8px; margin-bottom:8px; }
.load-card { border:1px solid #b8d0be; padding:10px; background:#f3f7e9; min-width:0; }
.load-card strong { font:12px monospace; }
.load-bars { display:flex; align-items:end; gap:3px; height:32px; margin-top:8px; }
.load-bars span { display:block; flex:1; background:#24836c; }
.load-bars span:nth-child(2) { background:#75ad73; }
.load-bars span:nth-child(3) { background:#ed935e; }
#stress-extra { margin-top:8px; }
.element-index { display:flex; flex-wrap:wrap; gap:8px; }
.element-index code { background:#edf4e8; border:1px solid #d0dfc8; padding:4px 8px; color:#294c22; font-size:12px; }
.catalog-search label { display:block; font-weight:bold; margin-bottom:8px; }
.catalog-search input { width:380px; }
.catalog-search output { margin-left:16px; color:var(--muted); }
.catalog-search p { font-size:13px; color:var(--muted); margin-top:12px; }
.page-footer { padding:24px 0 36px; border-top:1px solid var(--line); color:var(--muted); font-size:13px; }
[hidden] { display:none !important; }
::selection { background:#c4eaa5; color:#153f36; }
@media (max-width:1000px) { .card-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .form-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .load-group { grid-template-columns:repeat(4,minmax(0,1fr)); } }
@media (max-width:600px) { .workspace { padding:12px; } .hero { padding:22px; } .panel { padding:16px; } .card-grid,.form-grid { grid-template-columns:1fr; } .metrics { grid-template-columns:repeat(2,minmax(0,1fr)); } .inventory-stats { gap:22px; } .motion-hint { display:block; margin:0 0 20px; } .section-heading { display:block; } .load-group { grid-template-columns:repeat(3,minmax(0,1fr)); } h2 { font-size:24px; } }
@media (prefers-reduced-motion:reduce) { html { scroll-behavior:auto; } *,*::before,*::after { animation-play-state:paused !important; transition-duration:0s !important; } }
@media (forced-colors:active) { .hero,.load-card { border:1px solid CanvasText; } .load-bars span { background:Highlight; } }
@media print { .section-nav,.controls-panel,.motion-switch,.motion-label,.motion-hint,.catalog-search { display:none; } .workspace { max-width:none; padding:0; } .panel { break-inside:avoid; } body { background:white; color:black; } .hero { background:white; color:black; } .hero span,.hero p { color:black; } a { color:inherit; } }


/* Layout, raster, animation, scrolling, selectors and typography stress fixtures. */
.lab-section{--lab-ink:#18334f;--lab-accent:#267bc1;--lab-wash:#edf5fc;--lab-border:#bed2e4;color:var(--lab-ink);scroll-margin-top:24px}
.lab-section h2{margin:6px 0 16px}
.lab-section h3{margin:0 0 12px;font-size:18px}
.lab-section h4{margin:8px 0}
.lab-section p{line-height:1.55}
.lab-note{padding:14px 18px;border-inline-start:4px solid var(--lab-accent);background:var(--lab-wash)}
.lab-demo{min-width:0;padding:20px;border:1px solid var(--lab-border);background:#fff}
.lab-demo code{font-size:.9em;overflow-wrap:anywhere}
.lab-demo:focus-within{outline:2px solid #206c9f;outline-offset:3px}
.lab-cluster-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:20px;margin:24px 0}
.lab-cluster{min-width:0;padding:14px;border:1px solid var(--lab-border);background:#f6f9fc;container:lab-card / inline-size;contain:layout style}
.lab-cluster:nth-child(2n){--lab-accent:#127c6a;--lab-wash:#e8f7f2}
.lab-cluster:nth-child(3n){--lab-accent:#7548b1;--lab-wash:#f2ebfa}
.lab-cluster-heading,.lab-cluster-footer{display:flex;gap:12px;align-items:center;justify-content:space-between}
.lab-cluster-heading{padding:4px 0 14px}
.lab-cluster-heading h3{margin:0}
.lab-count{flex:none;border:1px solid var(--lab-border);border-radius:999px;padding:4px 8px;font-size:12px;white-space:nowrap}
.lab-cluster-footer{margin-top:12px;padding-top:10px;border-top:1px solid var(--lab-border);font-size:11px}
.lab-tile-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-flow:row dense;gap:10px}
.lab-tile{display:flex;flex-direction:column;min-width:0;gap:9px;padding:12px;border:1px solid var(--lab-border);border-radius:8px;background:#fff;box-shadow:0 2px 6px #1637540a}
.lab-tile header{display:flex;flex-wrap:wrap;gap:5px 8px;align-items:baseline}
.lab-tile strong{font-size:13px}
.lab-tile-index{color:var(--lab-accent);font-size:11px;font-variant-numeric:tabular-nums}
.lab-tile p{margin:0;font-size:12px;line-height:1.4;overflow-wrap:anywhere}
.lab-tile-meta{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-top:auto;padding-top:8px;font-size:10px}
.lab-tile-meta>span{padding:3px 5px;background:var(--lab-wash);color:var(--lab-accent);border-radius:3px}
.lab-tile-meta data{font-variant-numeric:tabular-nums}
.lab-meter{height:5px;overflow:hidden;border-radius:4px;background:#dce7f0}
.lab-meter>span{display:block;height:100%;background:var(--lab-accent)}
.lab-tone-2{border-inline-start:3px solid var(--lab-accent)}
.lab-tone-3{background:linear-gradient(135deg,#fff 50%,var(--lab-wash))}
.lab-tone-4{box-shadow:inset 0 0 0 3px var(--lab-wash)}
@container lab-card (min-width:420px){.lab-tile-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.lab-tile{padding:14px}.lab-tile strong{font-size:14px}}
@container lab-card (max-width:290px){.lab-tile-grid{grid-template-columns:1fr}.lab-cluster-heading{align-items:start}.lab-count{font-size:10px}}
.lab-layout-extras{margin-top:20px}
.lab-intrinsic{display:grid;grid-template-columns:min-content minmax(0,1fr) max-content;gap:8px;align-items:start}
.lab-intrinsic>span{padding:9px;background:var(--lab-wash);font-size:12px;overflow-wrap:anywhere}
.lab-area-grid{display:grid;grid-template-columns:70px minmax(0,1fr);grid-template-areas:"head head" "side body" "foot foot";gap:5px}
.lab-area-grid>*{padding:8px;background:#e9f2fa}
.lab-area-grid>header{grid-area:head}.lab-area-grid>aside{grid-area:side}.lab-area-grid>article{grid-area:body}.lab-area-grid>footer{grid-area:foot}
.lab-subgrid{display:grid;grid-template-columns:1fr 70px;gap:6px;margin-top:12px}
.lab-subgrid>div{display:grid;grid-template-columns:subgrid;grid-column:1/-1}
.lab-subgrid span{padding:5px;background:#e1f1eb}
.lab-contained{position:relative;height:135px;padding:15px;contain:paint;border:2px solid #168576;background:#e1f3ef}
.lab-contained>span{position:relative;z-index:1}
.lab-contained>i{position:absolute;right:-25px;bottom:-25px;width:95px;height:95px;background:#f58b45;transform:rotate(24deg)}
.lab-flex-orders{display:flex;flex-wrap:wrap;gap:8px;align-items:stretch}
.lab-flex-orders>span{flex:1 1 65px;padding:12px 8px;background:#e6eefb;font-size:12px}
.lab-flex-orders>span:nth-child(2){order:-1;background:#dcefe7}.lab-flex-orders>span:nth-child(3){flex-grow:3}

/* Effects */
.lab-effects-grid{margin:20px 0}
.lab-outset-stage{position:relative;padding:26px 18px 30px}
.lab-border-image{position:relative;padding:20px;border:6px solid transparent;border-image-source:linear-gradient(105deg,#7541c3,#e85188,#f59249);border-image-slice:1;border-image-width:1.8;border-image-outset:1;border-image-repeat:stretch;background:#fff}
.lab-overlay-chip{position:relative;z-index:1;display:inline-block;margin:-5px 0 0 18px;padding:6px 10px;background:#e0f0ed;border:1px solid #127c6a;font-size:12px}
.lab-clip-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.lab-polygon,.lab-ellipse{position:relative;isolation:isolate;display:grid;place-items:center;height:120px;background:#7442bd;color:#fff;font-size:13px}
.lab-polygon{clip-path:polygon(20% 0,80% 0,100% 35%,85% 100%,15% 100%,0 35%)}
.lab-ellipse{clip-path:ellipse(49% 45% at center)}
.lab-clip-child{position:absolute;bottom:-10px;right:-8px;width:55px;height:48px;background:#f58b45;transform:rotate(18deg);z-index:-1}
.lab-mask-content,.lab-mask-composite,.lab-mask-border{margin:10px 0;min-height:60px;padding:20px;background:#7040bd;color:#fff;font-weight:bold;font-size:13px}
.lab-mask-content{mask-image:linear-gradient(to right,transparent,black);mask-origin:content-box;mask-clip:content-box;mask-size:80% 100%;mask-position:center;mask-repeat:no-repeat;mask-mode:alpha}
.lab-mask-composite{mask-image:linear-gradient(black,black),radial-gradient(circle at center,black 0 24%,transparent 25%);mask-size:100% 100%;mask-repeat:no-repeat;mask-composite:exclude}
.lab-mask-border{mask-border-source:linear-gradient(to right,transparent,black);mask-border-slice:0 fill;mask-border-width:0;mask-border-repeat:stretch;-webkit-mask-box-image:linear-gradient(to right,transparent,black)}
.lab-image-effects{display:flex;flex-wrap:wrap;justify-content:space-around;gap:14px}
.lab-image-effects figure{flex:1 1 100px;margin:0;min-width:0;text-align:center}
.lab-image-effects img{max-width:100%;height:auto;object-fit:contain;object-position:center;image-rendering:auto}
.lab-image-effects figcaption{margin-top:9px;font-size:12px}
.lab-filter-chain{filter:grayscale(.35) sepia(.25) saturate(2.5) hue-rotate(55deg) contrast(1.2) brightness(.9)}
.lab-filter-shadow{filter:drop-shadow(7px 9px 5px #53387c80) blur(.3px)}
.lab-blend-stage{isolation:isolate;display:flex;flex-wrap:wrap;min-height:150px;align-items:center;justify-content:center;padding:20px;background-color:#eda66d;background-image:linear-gradient(35deg,#5475cf88,transparent),repeating-linear-gradient(90deg,#fff4 0 12px,transparent 12px 24px);background-blend-mode:multiply,screen}
.lab-blend-stage>span{padding:24px 8px;color:#fff;background:#7650bc;font-size:12px}
.lab-blend-multiply{mix-blend-mode:multiply}.lab-blend-screen{mix-blend-mode:screen}.lab-blend-difference{mix-blend-mode:difference}
.lab-corner-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.lab-corner-grid>div{min-height:68px;padding:22px 8px;text-align:center;background:#decef2;border:3px solid #7142b5;box-shadow:4px 5px 8px #35195320,inset 0 2px 5px #fff9;font-size:12px}
.lab-corner-round{border-radius:22px 5px 18px 9px}.lab-corner-elliptic{border-radius:40% 12% / 20% 46%}.lab-corner-squircle{border-radius:24px;corner-shape:squircle}.lab-corner-bevel{border-radius:20px;corner-shape:bevel}
.lab-glass-demo{margin-top:20px}
.lab-glass-stage{position:relative;isolation:isolate;overflow:hidden;min-height:300px;padding:26px;background-color:#29456c;background-image:repeating-conic-gradient(#375886 0 25%,#193857 0 50%);background-size:34px 34px}
.lab-glass-orb{position:absolute;width:180px;height:180px;border-radius:50%;z-index:-1;animation:lab-orbit 5s ease-in-out infinite alternate;animation-play-state:paused}
.lab-glass-orb-a{top:14px;left:10%;background:linear-gradient(45deg,#ffd069,#f77868)}
.lab-glass-orb-b{bottom:-20px;right:8%;background:linear-gradient(45deg,#67d9cb,#9caaf9);animation-delay:-2s}
.lab-glass-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0}
.lab-glass{position:relative;min-height:110px;margin:-6px;padding:30px 12px;display:grid;place-items:center;text-align:center;background:#ffffff24;border:1px solid #ffffff66;border-radius:18px;color:#fff;font-weight:bold;font-size:13px;backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px)}
.lab-glass:nth-child(2){backdrop-filter:blur(8px)}.lab-glass:nth-child(3){backdrop-filter:blur(12px)}.lab-glass:nth-child(4){backdrop-filter:blur(16px)}
.lab-glass:nth-child(5){backdrop-filter:blur(8px) saturate(2)}.lab-glass:nth-child(6){backdrop-filter:blur(10px) contrast(1.5)}
.lab-glass:nth-child(7){backdrop-filter:blur(7px) hue-rotate(75deg)}.lab-glass:nth-child(8){backdrop-filter:blur(12px) saturate(1.8) brightness(1.3)}
@keyframes lab-orbit{from{transform:translateX(-25px) translateY(0) scale(.8)}to{transform:translateX(100px) translateY(45px) scale(1.2)}}

/* Animation and compositing */
.lab-perspective-stage{height:220px;display:grid;place-items:center;perspective:650px;perspective-origin:45% 35%;background:#e7eff9;overflow:hidden}
.lab-cube{position:relative;width:100px;height:100px;transform-style:preserve-3d;transform:rotateX(-18deg) rotateY(28deg);animation:lab-turn 9s linear infinite;animation-play-state:paused}
.lab-cube>span{position:absolute;inset:0;display:grid;place-items:center;border:1px solid #ffffffb3;background:#2976bfcc;color:#fff;font-size:12px;font-weight:bold;backface-visibility:hidden}
.lab-cube-front{transform:translateZ(50px)}.lab-cube-back{transform:rotateY(180deg) translateZ(50px)}
.lab-cube-right{transform:rotateY(90deg) translateZ(50px)}.lab-cube-left{transform:rotateY(-90deg) translateZ(50px)}
.lab-cube-top{transform:rotateX(90deg) translateZ(50px)}.lab-cube-bottom{transform:rotateX(-90deg) translateZ(50px)}
.lab-cube>span:nth-child(2n){background:#9957bacc}
@keyframes lab-turn{from{transform:rotateX(-18deg) rotateY(28deg)}to{transform:rotateX(342deg) rotateY(388deg)}}
.lab-path-stage{position:relative;width:100%;height:155px;background:#e7eff9;overflow:hidden}
.lab-path-guide{position:absolute;left:24px;top:47px;width:225.175px;border-top:2px dashed #2675be;transform:rotate(12.308deg);transform-origin:left center}
.lab-path-marker{position:absolute;left:0;top:0;display:grid;place-items:center;width:32px;height:32px;color:white;background:#2675be;offset-path:path("M 24 48 L 244 96");offset-distance:16px;offset-anchor:center;offset-rotate:auto;animation:lab-travel 3.5s ease-in-out infinite alternate;animation-play-state:paused}
@keyframes lab-travel{from{offset-distance:16px}to{offset-distance:calc(100% - 16px)}}
.lab-curve-stage{position:relative;width:280px;max-width:100%;height:170px;overflow:hidden;background:#f0eaf8}
.lab-curve-stage svg{display:block;max-width:none}
.lab-curve-marker{position:absolute;left:0;top:0;width:28px;height:28px;display:grid;place-items:center;color:#fff;background:#7547b0;border-radius:50%;offset-path:path("M 28 85 C 28 10 250 10 250 85 C 250 160 28 160 28 85 Z");offset-distance:0%;offset-rotate:auto;animation:lab-curve 5s linear infinite;animation-play-state:paused}
@keyframes lab-curve{from{offset-distance:0%}to{offset-distance:100%}}
.lab-compose-stage{height:160px;padding:36px 28px;background:#e1eff9;overflow:hidden}
.lab-compose-box{display:grid;place-items:center;width:70px;height:70px;padding:8px;background:#207db8;color:white;translate:12px 0;rotate:3deg;scale:.9;transform:translateX(12px);transform-box:content-box;transform-origin:25% 75%;animation:lab-compose 2.8s ease-in-out infinite alternate;animation-composition:add;animation-play-state:paused}
@keyframes lab-compose{from{transform:translateX(0px) rotate(-8deg);opacity:.55}to{transform:translateX(115px) rotate(18deg);opacity:1}}
.lab-transition-target{display:block;margin:24px 8px 30px;padding:18px;border:2px solid #276ba0;border-radius:4px;background:#e4f1fb;color:#18334f;cursor:pointer;transition:transform .6s cubic-bezier(.2,.7,.2,1),background-color .4s linear,border-radius .8s ease,box-shadow .5s ease;transition-behavior:normal}
.lab-transition-target:is(:hover,:focus-visible){transform:translateX(12px) rotate(-2deg);background:#b8e7dc;border-radius:24px;box-shadow:7px 9px 0 #2b786a25}
.lab-steps-track{height:46px;background:repeating-linear-gradient(90deg,#e5edf7 0 29px,#c4d5e7 29px 30px);overflow:hidden}
.lab-steps-marker{display:inline-block;padding:12px;background:#4c68ad;color:#fff;font-size:12px;animation:lab-steps 3s steps(6,end) infinite alternate;animation-play-state:paused}
@keyframes lab-steps{from{transform:translateX(0)}to{transform:translateX(180px)}}
.lab-timeline-scroll{height:220px;overflow:auto;border:1px solid #b2cadf;scroll-timeline-name:--lab-progress;scroll-timeline-axis:block;overscroll-behavior:contain;scrollbar-gutter:stable}
.lab-timeline-content{position:relative;min-height:620px;padding:20px;background:linear-gradient(#edf5fb,#e2d6ef)}
.lab-timeline-content>p{margin:45px 0 130px;font-size:13px}
.lab-timeline-marker{position:sticky;top:14px;display:block;width:145px;padding:14px;background:#287bbe;color:white;font-size:12px;animation:lab-scroll-progress 1s linear both;animation-timeline:--lab-progress;animation-range:entry 0% exit 100%;animation-play-state:paused}
@keyframes lab-scroll-progress{from{transform:translateX(0);opacity:.35}to{transform:translateX(95px);opacity:1}}

/* Local scrollports */
.lab-snap-links{display:flex;gap:8px;margin-bottom:10px}
.lab-snap-links a{padding:6px 11px;border:1px solid #a9c8df;border-radius:4px;text-decoration:none;background:#edf5fb}
.lab-snap-track{display:flex;gap:16px;height:185px;padding:16px;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;scroll-padding-inline:16px;scroll-behavior:smooth;overscroll-behavior-x:contain;scrollbar-gutter:stable;scroll-marker-group:after;background:#e8f0f8}
.lab-snap-slide{flex:0 0 82%;min-width:0;padding:16px;scroll-snap-align:start;scroll-snap-stop:always;scroll-margin-inline:4px;background:#327bad;color:#fff;border-radius:8px}
.lab-snap-slide:nth-child(2n){background:#278574}.lab-snap-slide:nth-child(3){background:#8057b3}
.lab-snap-slide h4{margin:0}.lab-snap-slide p{font-size:12px}
.lab-sticky-scroll{height:220px;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#578cac #eaf1f8;background:#eaf1f8}
.lab-sticky-scroll section>h4{position:sticky;top:0;z-index:2;margin:0;padding:12px 14px;background:#315981;color:#fff}
.lab-sticky-scroll section:nth-child(2)>h4{background:#337c70}
.lab-sticky-scroll section>p{padding:9px 14px;margin:8px 0 36px}
.lab-attachment{height:215px;padding:14px;overflow:auto;border:1px solid #aac4d9;background-image:repeating-linear-gradient(to bottom,#d9ecf8 0,#d9ecf8 24px,#91b9d7 24px,#91b9d7 48px);background-size:100% 48px}
.lab-attachment>div{min-height:460px}
.lab-attachment p{padding:7px;background:#ffffffce;margin:6px 0 70px;font-size:13px}
.lab-attachment-local{background-attachment:local}.lab-attachment-fixed{background-attachment:fixed}
.lab-gutter-scroll{height:210px;overflow:auto;padding:8px;scrollbar-gutter:stable both-edges;scrollbar-width:thin;scrollbar-color:#218777 #edf5f3;overscroll-behavior:none;background:#e7f1ed}
.lab-gutter-scroll p{padding:10px;margin:4px 0 45px;background:#fff;white-space:normal;overflow-wrap:normal}
.lab-anchor-stage{position:relative;min-height:155px;padding:25px 10px;background:#ede7f8}
#lab-anchor-source{anchor-name:--lab-button;position:relative;display:block;padding:14px 20px;background:#7245b5;color:#fff;border:0}
.lab-anchor-note{position:absolute;left:105px;top:25px;max-width:150px;padding:10px;background:#f29349;font-size:12px}
@supports (position-area:right){.lab-anchor-note{left:auto;top:auto;position-anchor:--lab-button;position-area:right}}

/* State and selector probes */
.lab-choice{display:flex;align-items:center;gap:9px;padding:9px 0;font-size:14px}
.lab-choice input{accent-color:#188574}
.lab-check-target,.lab-has-target{padding:14px;margin:7px 0;border:2px solid #b7cde0;background:#eaf2f9;font-size:13px}
.lab-selector-controls:has(#lab-highlight:checked)>.lab-check-target{background:#beeadd;border-color:#188574}
.lab-selector-controls:has(input:checked)>.lab-has-target{border-inline-start:8px solid #7548ae}
.lab-selector-controls:has(#lab-mode-b:checked){--lab-accent:#a55624;background:#fff4e9}
.lab-selector-list{margin:0;padding:0;list-style:none}
.lab-selector-list>li{padding:8px 12px;border-bottom:1px solid #dce5ef;font-size:13px}
.lab-selector-list>li:nth-child(2n){background:#edf4fb}
.lab-selector-list>li:is(.lab-featured,:first-child){font-weight:bold}
.lab-selector-list>li:not(.lab-featured):nth-child(odd){color:#42698a}
.lab-selector-list>li:nth-child(3n){border-inline-start:4px solid #8056b6}
.lab-attribute-samples{display:flex;flex-direction:column;gap:7px}
.lab-attribute-samples>[data-lab-state$="ready"]{background:#daf0e6}
.lab-attribute-samples>[data-lab-state^="work"]{background:#fff0cd}
.lab-attribute-samples>[data-lab-kind~="navigation"]{font-weight:bold;text-decoration-thickness:2px}
.lab-attribute-samples>[lang|="de"]{border-inline-start:4px solid #187d68}
.lab-attribute-samples>*{padding:8px;font-size:13px}
.lab-sibling-start+p{background:#e8f0fb}.lab-sibling-start~p{padding-inline-start:14px;border-inline-start:2px solid #3c82b9}
.lab-focus-demo label{display:block;margin:12px 0 5px;font-size:13px}
.lab-focus-demo input{display:block;width:100%;min-width:0;padding:10px;border:2px solid #b6cddd;border-radius:4px;color:#173650;background:#fff;font:inherit}
.lab-focus-demo input:placeholder-shown{border-style:dashed}
.lab-focus-demo input:focus-visible{outline:3px solid #65b5ef;outline-offset:2px}
.lab-focus-demo input:invalid:not(:placeholder-shown){border-color:#b64651}
.lab-focus-demo input:valid:not(:placeholder-shown){border-color:#188574}
.lab-focus-demo:focus-within{background:#f0f8ff}
.lab-focus-demo button:disabled{margin-top:14px;padding:9px;opacity:.55;cursor:not-allowed}
.lab-variable-outer{--lab-local-gap:12px;--lab-local-color:#397db0;padding:var(--lab-local-gap);border:2px solid var(--lab-local-color);background:#edf5fa;font-size:13px}
.lab-variable-middle{--lab-local-gap:18px;margin-top:10px;padding:var(--lab-local-gap);border:2px dashed var(--lab-local-color)}
.lab-variable-inner{--lab-local-color:#8050b8;margin-top:10px;padding:var(--lab-missing-gap,10px);background:var(--lab-local-color);color:white}
.lab-counter-list,.lab-counter-list ol{counter-reset:lab-step;list-style:none;padding-left:0}
.lab-counter-list li{counter-increment:lab-step;margin:10px 0;padding-left:2px;font-size:13px}
.lab-counter-list li::before{content:counters(lab-step,".") " ";display:inline-block;min-width:30px;color:#1c79b3;font-weight:bold}
.lab-counter-list ol{margin-left:22px}
.lab-selection::selection{background:#8555b4;color:#fff}

/* Text layout */
.lab-columns{columns:2 145px;column-gap:22px;column-rule:1px solid #a8c4d9;column-fill:balance;orphans:2;widows:2;font-size:13px}
.lab-columns p{margin-top:0}.lab-columns h4{column-span:all;break-after:avoid;padding:7px;background:#e9f3fa}
.lab-shape-story{display:flow-root;font-size:14px;line-height:1.65}
.lab-float-circle{float:left;width:120px;height:120px;display:grid;place-items:center;margin:0 10px 6px 0;border-radius:50%;shape-outside:circle(50%);shape-margin:10px;background:linear-gradient(135deg,#277db4,#7354b2);color:#fff;font-size:12px;font-weight:bold}
.lab-shape-story p{margin-top:0}.lab-cleared{clear:both;padding-top:10px;border-top:1px solid #d0dfeb}
.lab-ruby-row{padding:10px 0;font-size:23px;line-height:2.2}.lab-ruby-row ruby{margin-right:12px;ruby-align:space-around;ruby-position:over}
.lab-ruby-row rt{font-size:11px}.lab-ruby-under ruby{ruby-position:under;ruby-align:start}
.lab-writing-pair{display:flex;gap:14px;height:140px;margin-top:20px}
.lab-writing-pair p{margin:0;padding:12px;background:#eee8f8;font-size:15px}
.lab-writing-rl{writing-mode:vertical-rl;text-orientation:mixed}.lab-writing-lr{writing-mode:vertical-lr;text-orientation:upright}
.lab-hyphens{max-width:240px;hyphens:auto;hyphenate-character:"-";hyphenate-limit-chars:8 3 3;overflow-wrap:break-word}
.lab-bidi{unicode-bidi:isolate;padding:14px;background:#e9f4f0;font-size:22px;text-align:start}
.lab-quotes{quotes:"„" "“" "‚" "‘";margin:14px 0;padding:10px 14px;border-inline-start:4px solid #7c53b0;background:#f0eaf8}
.lab-quotes q::before{content:open-quote}.lab-quotes q::after{content:close-quote}
.lab-font-features{font-family:Georgia,serif;font-kerning:normal;font-variant-ligatures:common-ligatures discretionary-ligatures;font-feature-settings:"liga" 1,"kern" 1;font-optical-sizing:auto;font-size-adjust:.5;font-size:23px}
.lab-tabular{font-family:Arial,sans-serif;font-variant-numeric:tabular-nums slashed-zero lining-nums;font-feature-settings:"tnum" 1,"zero" 1;letter-spacing:.04em;line-height:1.55}
.lab-decoration{text-decoration-line:underline overline;text-decoration-style:wavy;text-decoration-color:#9961b5;text-decoration-thickness:2px;text-underline-offset:5px;text-decoration-skip-ink:auto;line-height:2;text-shadow:1px 2px 1px #5a78a133}
.lab-emphasis{text-emphasis:filled sesame #9d5464;text-emphasis-position:over right;line-height:2.1}
.lab-caps{font-variant-caps:small-caps;font-synthesis:none;font-stretch:condensed}
.lab-clamp{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;line-clamp:3;overflow:hidden;line-height:1.6;padding:0 12px;background:#fff0e3}
.lab-balance{text-wrap:balance;max-width:280px;font-size:19px;font-weight:bold}
.lab-ellipsis{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:8px;background:#edf4fb}
.lab-tabs{max-width:100%;overflow:auto;tab-size:8;white-space:pre;font-size:12px;padding:14px;border:1px solid #cbdbe7;background:#f6f9fc}
@media(max-width:700px){.lab-demo{padding:15px}.lab-glass-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.lab-glass-stage{min-height:450px}.lab-intrinsic{grid-template-columns:min-content minmax(0,1fr)}.lab-intrinsic>span:last-child{grid-column:1/-1}.lab-cluster-grid{grid-template-columns:1fr}.lab-perspective-stage{height:200px}}
@media(prefers-reduced-motion:reduce){.lab-section .motion{animation-duration:0s!important;animation-play-state:paused!important}.lab-transition-target{transition:none}.lab-snap-track{scroll-behavior:auto}}

html-css-stress-css-layout.css:
:root { color-scheme: light; --ink:#173630; --muted:#49685f; --paper:#f3f5ef; --panel:#fff; --line:#c9d9d0; --accent:#087f72; --warm:#fa7b43; --space:20px; font-family:Arial,sans-serif; font-size:16px; }
* { box-sizing:border-box; }
html { scroll-behavior:smooth; scroll-padding-top:20px; }
body { margin:0; background:var(--paper); color:var(--ink); line-height:1.5; }
.workspace { max-width:1480px; margin:0 auto; padding:28px; }
a { color:#076a60; text-underline-offset:3px; }
a:hover { color:#974318; }
:focus-visible { outline:3px solid #b44409; outline-offset:4px; }
.skip-link { position:fixed; top:8px; left:8px; transform:translateY(-150%); background:#fff; padding:12px; z-index:1000; }
.skip-link:focus { transform:translateY(0); }
.hero { padding:32px 36px 30px; background:#153f36; color:#fff; border-radius:4px; }
.hero a { color:#bdedc4; }
.hero-top { display:flex; justify-content:space-between; gap:16px; flex-wrap:wrap; font-size:13px; }
.edition,.eyebrow { font-size:12px; letter-spacing:.12em; text-transform:uppercase; font-weight:bold; }
.eyebrow { color:var(--accent); margin:0 0 8px; }
.hero .eyebrow { color:#b7e5b5; margin-top:38px; }
h1 { font-size:clamp(42px,6vw,80px); line-height:1.02; letter-spacing:-.035em; margin:14px 0 20px; }
h1 span { color:#bfe8aa; }
.lead { font-size:20px; max-width:660px; }
.inventory-stats { display:flex; gap:48px; flex-wrap:wrap; border-top:1px solid #538071; margin-top:28px; padding-top:10px; }
.inventory-stats p { margin:8px 0; }
.inventory-stats strong { display:block; font-size:32px; line-height:1.2; }
.inventory-stats span { font-size:13px; color:#d1e6d9; }
.scope-note { max-width:970px; color:#d1e6d9; font-size:13px; margin-top:20px; }
.section-nav { display:flex; gap:10px 20px; flex-wrap:wrap; padding:20px 0; border-bottom:1px solid var(--line); margin-bottom:24px; }
.section-nav a { font-weight:bold; font-size:14px; }
.panel { background:var(--panel); border:1px solid var(--line); padding:24px; margin-bottom:24px; min-width:0; }
.section-heading { display:flex; gap:16px; justify-content:space-between; align-items:start; margin-bottom:16px; }
h2 { font-size:28px; line-height:1.2; margin:0 0 16px; letter-spacing:-.02em; }
h3 { font-size:18px; margin:0 0 12px; }
h4,h5,h6 { margin:8px 0; }
p { margin:0 0 14px; }
.chip { background:#e5f0d9; color:#26491a; padding:5px 10px; font-size:12px; white-space:nowrap; border-radius:20px; }
.control-row { display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin:18px 0; }
button,input,select,textarea { font:inherit; accent-color:var(--accent); }
button,input[type=button],input[type=submit],input[type=reset] { padding:9px 14px; border:1px solid #087f72; background:#e1f3ec; color:#123e33; cursor:pointer; border-radius:3px; }
button:hover { background:#ccebdc; }
button:disabled { color:#65736e; border-color:#b7c5be; background:#eef1ed; cursor:default; }
#benchmark-start { background:#087f72; color:#fff; }
input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]):not([type=image]):not([type=hidden]),select,textarea { max-width:100%; min-width:0; padding:9px 10px; border:1px solid #78958a; background:#fff; color:var(--ink); border-radius:3px; }
input:read-only { background:#f1f4ef; }
input:disabled,select:disabled { opacity:.65; }
input:user-invalid { border-color:#b53928; background:#fff0ea; }
input::placeholder,textarea::placeholder { color:#64776f; opacity:1; }
.metrics { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:12px; margin:20px 0; }
.metrics>div { border-top:2px solid #a9c4b5; padding:12px 0; }
.metrics span { display:block; color:var(--muted); font-size:12px; }
.metrics output { font-family:monospace; font-size:24px; font-weight:bold; }
#benchmark-status { color:var(--muted); font-size:14px; }
details { border-top:1px solid var(--line); padding:14px 0; }
summary { cursor:pointer; font-weight:bold; margin-bottom:8px; }
.motion-switch { margin:0 8px 24px 4px; width:18px; height:18px; vertical-align:middle; }
.motion-label { font-weight:bold; }
.motion-hint { color:var(--muted); font-size:13px; margin-left:16px; }
#run-motion ~ section .motion { animation-play-state:paused; }
#run-motion:checked ~ section .motion { animation-play-state:running; }
.card-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:18px; }
.specimen { margin:0; border:1px solid #d3dfd7; padding:18px; min-width:0; overflow-wrap:anywhere; }
.specimen p:last-child { margin-bottom:0; }
pre { padding:12px; background:#eff4ee; overflow:auto; font-size:13px; }
code,kbd,samp { font-family:monospace; }
kbd { border:1px solid #a5b8ac; border-bottom-width:3px; padding:1px 5px; border-radius:3px; }
blockquote { margin:16px 0; border-left:3px solid var(--warm); padding-left:14px; color:#4c645a; }
blockquote footer { font-size:13px; }
dt { font-weight:bold; } dd { margin:0 0 10px 20px; }
menu { padding-left:20px; }
.ruby-line { line-height:3; font-size:22px; }
.callout { background:#edf5e7; padding:18px; margin:20px 0; }
fieldset { border:1px solid var(--line); padding:18px; margin:18px 0; min-width:0; }
legend { padding:0 8px; font-weight:bold; }
.form-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:18px; }
.form-grid>label { display:flex; flex-direction:column; gap:6px; font-size:14px; }
.form-grid>div>label,.radio-group label { display:block; margin:8px 0; }
.radio-group { margin:0; padding:10px; }
.gauges { display:flex; flex-wrap:wrap; gap:24px; }
.gauges label { display:flex; gap:10px; flex-direction:column; }
progress,meter { width:180px; height:20px; }
.custom-select,.custom-select::picker(select) { appearance:base-select; }
dialog { color:var(--ink); background:#fff; border:1px solid var(--accent); max-width:480px; padding:28px; }
dialog::backdrop { background:rgb(10 40 32 / .65); backdrop-filter:blur(5px); }
dialog label { display:block; margin-bottom:18px; }
[popover] { max-width:320px; padding:20px; border:2px solid var(--accent); background:#fff; color:var(--ink); }
.table-scroll { overflow:auto; max-height:400px; scrollbar-gutter:stable; }
.data-table { width:100%; min-width:620px; border-collapse:collapse; table-layout:fixed; }
.data-table caption { text-align:left; color:var(--muted); padding-bottom:12px; font-size:13px; }
.data-table th,.data-table td { border:1px solid #c4d6ca; padding:10px 12px; text-align:left; }
.data-table thead { position:sticky; top:0; z-index:2; background:#dbeade; }
.data-table tbody tr:nth-child(even) { background:#f0f5ee; }
.data-table tbody tr:hover { background:#e3efcb; }
.data-table .col-index { width:20%; } .data-table .col-value { background:#eff4df; }
.data-table tfoot { font-weight:bold; background:#dbeade; }
img,video,canvas,iframe,object,embed,svg { max-width:100%; }
audio { width:100%; margin:8px 0; }
video,canvas { display:block; height:auto; margin:12px 0; }
iframe { border:1px solid var(--line); }
.embedded-stack { display:flex; flex-direction:column; align-items:flex-start; gap:19px; }
figcaption { color:var(--muted); font-size:13px; margin-top:10px; }
.inline-svg { display:block; margin-top:16px; }
stress-note { display:block; }
math { font-size:28px; min-height:90px; }
.load-seed { display:block; }
.load-group { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:8px; margin-bottom:8px; }
.load-card { border:1px solid #b8d0be; padding:10px; background:#f3f7e9; min-width:0; }
.load-card strong { font:12px monospace; }
.load-bars { display:flex; align-items:end; gap:3px; height:32px; margin-top:8px; }
.load-bars span { display:block; flex:1; background:#24836c; }
.load-bars span:nth-child(2) { background:#75ad73; }
.load-bars span:nth-child(3) { background:#ed935e; }
#stress-extra { margin-top:8px; }
.element-index { display:flex; flex-wrap:wrap; gap:8px; }
.element-index code { background:#edf4e8; border:1px solid #d0dfc8; padding:4px 8px; color:#294c22; font-size:12px; }
.catalog-search label { display:block; font-weight:bold; margin-bottom:8px; }
.catalog-search input { width:380px; }
.catalog-search output { margin-left:16px; color:var(--muted); }
.catalog-search p { font-size:13px; color:var(--muted); margin-top:12px; }
.page-footer { padding:24px 0 36px; border-top:1px solid var(--line); color:var(--muted); font-size:13px; }
[hidden] { display:none !important; }
::selection { background:#c4eaa5; color:#153f36; }
@media (max-width:1000px) { .card-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .form-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .load-group { grid-template-columns:repeat(4,minmax(0,1fr)); } }
@media (max-width:600px) { .workspace { padding:12px; } .hero { padding:22px; } .panel { padding:16px; } .card-grid,.form-grid { grid-template-columns:1fr; } .metrics { grid-template-columns:repeat(2,minmax(0,1fr)); } .inventory-stats { gap:22px; } .motion-hint { display:block; margin:0 0 20px; } .section-heading { display:block; } .load-group { grid-template-columns:repeat(3,minmax(0,1fr)); } h2 { font-size:24px; } }
@media (prefers-reduced-motion:reduce) { html { scroll-behavior:auto; } *,*::before,*::after { animation-play-state:paused !important; transition-duration:0s !important; } }
@media (forced-colors:active) { .hero,.load-card { border:1px solid CanvasText; } .load-bars span { background:Highlight; } }
@media print { .section-nav,.controls-panel,.motion-switch,.motion-label,.motion-hint,.catalog-search { display:none; } .workspace { max-width:none; padding:0; } .panel { break-inside:avoid; } body { background:white; color:black; } .hero { background:white; color:black; } .hero span,.hero p { color:black; } a { color:inherit; } }


.property-group{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;margin:12px 0}
.property-card{min-width:0;overflow:hidden;contain:paint;background:#fff;border:1px solid #b8cbe2;padding:10px}
.property-card h3{font:600 14px/1.35 Arial;margin:0 0 5px;overflow-wrap:anywhere;color:#173d68}
.property-card p{font:11px/1.35 Arial;margin:0 0 7px;color:#42556c;overflow-wrap:anywhere;min-height:30px}
.probe-stage{position:relative;contain:layout paint;isolation:isolate;overflow:hidden;height:116px;background:#edf3fa;padding:8px}
.property-probe{display:block;box-sizing:border-box;width:140px;max-width:100%;min-height:34px;padding:7px;border:2px solid #80a6d4;background:#d4e4f6;color:#173d68;font:14px/1.4 Arial;overflow-wrap:anywhere}
.property-probe span{background:#f2d5a7;padding:2px}
.property-probe input{max-width:100%}
.counter-probe span::before{content:counter(sample) ". ";counter-increment:sample}
.transition-probe:hover,.transition-probe:focus{transform:translateX(12px);opacity:.6}
@keyframes catalog-pulse{from{transform:translateX(0px);opacity:.4}to{transform:translateX(22px);opacity:1}}
@media(prefers-reduced-motion:reduce){.property-probe{animation-play-state:paused!important;transition-duration:0s!important}}

